    blues = [(x, y) for y in range(64) for x in range(64)
             if board[y][x] == 11]
    bx = min(x for x, y in blues)
    yellows = [(x, y) for y in range(15) for x in range(64)
               if board[y][x] == 4]
    grays = [(x, y) for y in range(15) for x in range(64)
             if board[y][x] == 5]
    return {"original": original, "base": base, "bx": bx,
            "initial": (min(x for x, y in yellows),
                        min(x for x, y in grays)),
